const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const icons={today:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',inbox:'<path d="M4 5h16v14H4zM4 6l8 6 8-6"/>',pipeline:'<path d="M5 4v16M12 4v16M19 4v16M3 7h4M10 12h4M17 9h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M7 15h3M14 15h3"/>',followups:'<path d="M4 10a8 8 0 111 8M4 4v6h6M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.inbox}</svg>`;
const navs=[['today','Today'],['inbox','Inbox'],['pipeline','Client pipeline'],['calendar','Calendar'],['followups','Follow-ups'],['settings','Business setup']];
const stages=['New inquiry','Qualified','Meeting booked','Proposal sent','Won','Lost'];
let clients=[
{id:1,name:'Maya Chen',company:'Bloom & Co',initials:'MC',color:'purple',email:'maya@bloom.example',subject:'A fresh direction for our brand',message:'Hi Alex! We’re a growing skincare brand and need help with our positioning before a November launch. Our budget is around $8,000. Is this something you can help with?',stage:'New inquiry',value:8000,source:'Website inquiry',time:'12 min ago',kind:'reply',due:'2026-09-24',need:true,draft:'Hi Maya, thanks for reaching out! A brand positioning engagement ahead of your November launch sounds like a good fit. Your $8,000 budget is within our project range.\n\nWhat is the main challenge you want the new positioning to solve? Once I know a little more, we can schedule a 30-minute discovery call to discuss the launch.\n\nBest,\nAlex',sent:[],note:'Brand strategy · $8k budget · November launch'},
{id:2,name:'James Wilson',company:'Forma Digital',initials:'JW',color:'blue',email:'james@forma.example',subject:'Re: Growth strategy proposal',message:'Thanks for putting this together, Alex. I’m reviewing the growth strategy proposal with our co-founder and should have feedback this week.',stage:'Proposal sent',value:12500,source:'Email',time:'3 days ago',kind:'followup',due:'2026-09-24',need:true,draft:'Hi James, checking in on the growth strategy proposal. Have you and your co-founder had a chance to review it? Happy to answer questions about the scope or walk through the next steps together.\n\nBest,\nAlex',sent:[],note:'Growth strategy · Proposal awaiting feedback'},
{id:3,name:'Sofia Rodriguez',company:'Atelier Collective',initials:'SR',color:'pink',email:'sofia@atelier.example',subject:'Let’s talk about our launch',message:'The strategy engagement sounds like a good fit. We’re planning a January launch and would love to chat about the process. Do you have time this week?',stage:'Qualified',value:6000,source:'Referral',time:'48 min ago',kind:'reply',due:'2026-09-24',need:true,draft:'Hi Sofia, I’d love to hear more about your January launch. A 30-minute discovery call would be a great next step. I can share available times once we confirm the best day for you.\n\nBest,\nAlex',sent:[],note:'Launch strategy · Ready for a discovery call'},
{id:4,name:'Daniel Park',company:'Lumen Labs',initials:'DP',color:'green',email:'daniel@lumen.example',subject:'Discovery call confirmed',message:'Thursday at 10:00 AM works for me. Looking forward to discussing how we can improve our sales process.',stage:'Meeting booked',value:9000,source:'Email',time:'Yesterday',kind:'reply',need:false,sent:[],note:'Sales process · Discovery call'},
{id:5,name:'Emma Brooks',company:'Fieldwork',initials:'EB',color:'orange',email:'emma@fieldwork.example',subject:'Workshop planning',message:'I’ve shared the current customer journey map. Let’s review it at our workshop planning call on Thursday.',stage:'Meeting booked',value:7500,source:'Referral',time:'Yesterday',kind:'reply',need:false,sent:[],note:'Customer experience · Workshop planning'},
{id:6,name:'Oliver Reed',company:'Common Ground',initials:'OR',color:'blue',email:'oliver@common.example',subject:'A few questions about the scope',message:'Could we talk through the deliverables on Friday? We’re particularly interested in the research phase.',stage:'Meeting booked',value:5500,source:'Email',time:'Yesterday',kind:'reply',need:false,sent:[],note:'Positioning research · Scope review'},
{id:7,name:'Ava Patel',company:'Studio Fern',initials:'AP',color:'green',email:'ava@fern.example',subject:'Q4 strategy partnership',message:'We’re discussing the proposal at our Monday leadership meeting. Could you check back with us next week?',stage:'Proposal sent',value:6500,source:'Website inquiry',time:'2 days ago',kind:'followup',due:'2026-09-28',need:true,draft:'Hi Ava, I hope the leadership meeting went well. I wanted to check in on the Q4 strategy proposal. Are there any questions I can help answer?\n\nBest,\nAlex',sent:[],note:'Q4 strategy · Follow up after Monday meeting'},
{id:8,name:'Noah Kim',company:'Arc Partners',initials:'NK',color:'orange',email:'noah@arc.example',subject:'Exploring a smaller strategy session',message:'We’re looking for a focused strategy session to align our small team. Our budget is $3,500 and timing is flexible.',stage:'Qualified',value:3500,source:'Email',time:'Yesterday',kind:'reply',need:false,sent:[],note:'Team alignment · Budget needs review'}];
let events=[{id:1,client:4,date:'2026-09-24',time:'10:00',title:'Discovery call',duration:30},{id:2,client:5,date:'2026-09-24',time:'14:00',title:'Workshop planning',duration:30},{id:3,client:6,date:'2026-09-25',time:'11:00',title:'Scope review',duration:30}];
let settings={name:'Northstar Studio',owner:'Alex Carter',services:'Brand strategy, growth strategy, and customer experience consulting',minimum:5000,tone:'Warm and professional',questions:'What would you like to achieve? What is your timeline? What budget have you set aside?',auto:false};
let view='today',selected=1,inboxFilter='all',inboxQuery='',weekOffset=0,activity=[],nextClient=9,nextEvent=4,toastTimer;
const find=id=>clients.find(c=>c.id===Number(id));
const due=()=>clients.filter(c=>c.need&&c.due<='2026-09-24'&&!['Won','Lost'].includes(c.stage));
const openClients=()=>clients.filter(c=>!['Won','Lost'].includes(c.stage));
const avatar=c=>`<span class="avatar ${c.color}">${esc(c.initials)}</span>`;
const badge=c=>`<span class="pill ${c.stage==='Won'?'green':c.stage==='Lost'?'gray':''}">${esc(c.stage)}</span>`;
const prettyDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const timeLabel=t=>new Date('2026-09-24T'+t).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function draftFor(c){let first=c.name.split(' ')[0],owner=settings.owner.split(' ')[0];let intro=settings.tone==='Concise and direct'?`Hi ${first}, thanks for reaching out.`:settings.tone==='Friendly and conversational'?`Hi ${first}, great to hear from you!`:`Hi ${first}, thank you for getting in touch.`;return `${intro}\n\nAt ${settings.name}, we help clients with ${settings.services.toLowerCase()}. ${c.value<settings.minimum?'Our engagements typically start at '+money(settings.minimum)+'. Would that work for your budget? ':''}${settings.questions}\n\nOnce we know a little more, we can find a time for a discovery call.\n\nBest,\n${owner}`}
function heading(title,sub,action=''){return `<div class="page-heading compact"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function navTo(next){if(!navs.some(n=>n[0]===next))return;view=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'})}
function render(){document.title=`${navs.find(n=>n[0]===view)[1]} · Relay`;$('#nav').innerHTML=navs.map(([key,label])=>`<button data-view="${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='inbox'&&due().length?`<span class="count">${due().length}</span>`:''}</button>`).join('');$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${navs.find(n=>n[0]===view)[1]}`;$('.workspace strong').textContent=settings.name;$('.profile strong').textContent=settings.owner;$('#main').innerHTML=({today:todayView,inbox:inboxView,pipeline:pipelineView,calendar:calendarView,followups:followupsView,settings:settingsView}[view])()}
function todayView(){let pending=due();return `<div class="page-heading"><div><div class="eyebrow">YOUR DAILY BRIEF</div><h1>A little less busy.<br><span>A lot more momentum.</span></h1><p>Good morning, ${esc(settings.owner.split(' ')[0])}. ${pending.length?`You have ${pending.length} suggestions ready to review.`:'You’re all caught up on today’s suggestions.'}</p></div><button class="button primary" data-view="inbox">Review suggestions <span>↗</span></button></div><section class="metrics" aria-label="Workspace summary"><article><span>Open opportunities ${icon('pipeline')}</span><strong>${openClients().length}<small>clients in motion</small></strong><div class="metric-bars">${[35,45,40,60,55,70,85,100].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></article><article><span>Pipeline value ${icon('today')}</span><strong>${money(openClients().reduce((s,c)=>s+c.value,0))}<small>potential project fees, not revenue</small></strong><div class="metric-line"></div></article><article><span>Needs your approval ${icon('inbox')}</span><strong>${pending.length}<small>${pending.length?'drafts ready for your personal touch':'nothing waiting on you today'}</small></strong><div class="stacked-avatars">${pending.slice(0,3).map(avatar).join('')}</div></article></section><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><h2>Your next best moves</h2><span class="pill">✧ Prepared by Relay</span></div>${pending.length?pending.map(c=>`<div class="move-row">${avatar(c)}<div><div class="row-title">${esc(c.name)} <span>· ${esc(c.company)}</span></div><p>${c.kind==='followup'?'Keep the conversation going on your proposal.':c.stage==='Qualified'?'A good-fit client is ready for the next step.':'A new inquiry is ready for your reply.'}</p><div class="row-meta"><span>${c.kind==='followup'?'Proposal follow-up':'Suggested reply'}</span><span>${money(c.value)} opportunity</span></div></div><button class="button small" data-review="${c.id}">Review ${c.kind==='followup'?'follow-up':'reply'} <span>↗</span></button></div>`).join(''):'<div class="empty">✓ All caught up.<p>Today’s replies and follow-ups are taken care of.</p></div>'}</section><section class="panel activity-panel"><div class="panel-head"><h2>Recent activity</h2><span class="muted text-small">Today</span></div>${(activity.length?activity:[{text:'Discovery call scheduled with Lumen Labs',time:'9:02 AM'},{text:'Growth proposal moved to Proposal sent',time:'8:45 AM'}]).slice(0,4).map(a=>`<div class="activity-row"><span class="activity-check">✓</span><span>${esc(a.text)}</span><small>${a.time}</small></div>`).join('')}</section></div><aside><section class="panel schedule-panel"><div class="panel-head"><h2>On your calendar</h2><button class="icon-button" data-view="calendar" aria-label="Open calendar">↗</button></div><div class="calendar-date"><span>24</span><div>Thursday<small>September 2026 · Eastern</small></div></div>${events.filter(e=>e.date==='2026-09-24').sort((a,b)=>a.time.localeCompare(b.time)).map(e=>eventRow(e)).join('')||'<div class="empty">A clear calendar today.</div>'}<button class="button wide subtle" data-view="calendar">View full calendar →</button></section><section class="insight"><div class="eyebrow">A MOMENT OF FOCUS</div><h2>Good relationships<br>start with showing up.</h2><p>Relay handles the follow-through.<br>You bring the expertise.</p><span class="insight-decoration" aria-hidden="true">↗</span></section></aside></div>`}
function eventRow(e){let c=find(e.client);return `<button class="event-row" data-event="${e.id}"><span class="event-time">${timeLabel(e.time)}</span><div><strong>${esc(e.title)}</strong><span>${esc(c.company)}</span><small>${e.duration} min · Video call</small></div></button>`}
function inboxView(){let matches=clients.filter(c=>(inboxFilter!=='pending'||due().includes(c))&&`${c.name} ${c.company} ${c.subject}`.toLowerCase().includes(inboxQuery.toLowerCase()));if(!matches.some(c=>c.id===selected))selected=matches[0]?.id;const c=find(selected);return heading('Every conversation. One place.','Thoughtful replies, with you in control.',`<button class="button primary" data-action="new-inquiry">＋ Try a new inquiry</button>`)+`<div class="inbox-layout panel"><section class="thread-list"><div class="inbox-controls"><label class="search-label"><span>⌕</span><input id="search" aria-label="Search conversations" placeholder="Search conversations" value="${esc(inboxQuery)}"></label><div class="tabs"><button data-filter="all" aria-pressed="${inboxFilter==='all'}" class="${inboxFilter==='all'?'selected':''}">All conversations</button><button data-filter="pending" aria-pressed="${inboxFilter==='pending'}" class="${inboxFilter==='pending'?'selected':''}">Needs review <b>${due().length}</b></button></div></div>${matches.map(x=>`<button class="thread ${x.id===selected?'selected':''}" data-thread="${x.id}"><div class="thread-top">${avatar(x)}<div><strong>${esc(x.name)}</strong><small>${esc(x.company)}</small></div>${due().includes(x)?'<span class="unread" aria-label="Needs review"></span>':''}</div><strong class="subject">${esc(x.subject)}</strong><p>${esc(x.sent.at(-1)?.text||x.message)}</p><div class="thread-bottom"><span>${esc(x.time)}</span><span>${x.sent.length?'Replied':x.source}</span></div></button>`).join('')||'<div class="empty">No conversations match.</div>'}</section><section class="conversation">${c?conversation(c):'<div class="empty">No conversation selected.<p>Choose All conversations or clear your search.</p></div>'}</section></div>`}
function conversation(c){if(!c.draft&&!c.sent.length)c.draft=draftFor(c);return `<div class="conversation-head"><div>${avatar(c)}<div><h2>${esc(c.name)}</h2><p>${esc(c.email)}</p></div></div><button class="button small" data-book="${c.id}">${events.some(e=>e.client===c.id)?'Manage meeting':'Book meeting'}</button></div><div class="client-context">${badge(c)}<span>${money(c.value)} opportunity</span><button class="text-button" data-client="${c.id}">View client ↗</button></div><div class="messages"><div class="message-heading">${esc(c.subject)}</div><div class="message"><div class="message-label">${esc(c.name)} <span>${esc(c.time)}</span></div><p>${esc(c.message)}</p></div>${c.sent.map(s=>`<div class="message outgoing"><div class="message-label">${esc(settings.owner)} <span>Demo reply</span></div><p>${esc(s.text)}</p></div>`).join('')}</div><div class="composer"><div class="composer-head"><span class="spark">✧</span><strong>${c.sent.length?'Write another reply':'Suggested reply'}</strong><span class="pill">${esc(settings.tone)}</span></div><textarea id="reply-text" aria-label="Reply draft" rows="7">${esc(c.draft)}</textarea><div class="composer-footer"><span>Review before sending · demo only</span><button class="button primary" data-send="${c.id}">Approve & send ↗</button></div></div>`}
function pipelineView(){return heading('Relationships in motion.','Track each opportunity from the first hello to a signed yes.',`<div class="pipeline-total">${money(openClients().reduce((s,c)=>s+c.value,0))}<small>open pipeline</small></div>`)+`<div class="kanban">${stages.map((stage,i)=>{let group=clients.filter(c=>c.stage===stage);return `<section class="kanban-column"><div class="column-heading"><span class="stage-dot s${i}"></span><h2>${stage}</h2><span>${group.length}</span></div><div class="column-total">${money(group.reduce((s,c)=>s+c.value,0))}</div>${group.map(c=>`<button class="client-card" data-client="${c.id}"><div class="client-card-top">${avatar(c)}<span>↗</span></div><h3>${esc(c.company)}</h3><p>${esc(c.name)}</p><div class="card-note">${esc(c.note)}</div><div class="client-card-bottom"><strong>${money(c.value)}</strong><span>${due().includes(c)?'Needs review':'View details'}</span></div></button>`).join('')||'<div class="column-empty">No clients here yet</div>'}</section>`}).join('')}</div><p class="page-note">Select a client to review their details, update their stage, or book a meeting.</p>`}
function getWeek(){return Array.from({length:5},(_,i)=>{let d=new Date('2026-09-21T12:00:00');d.setDate(d.getDate()+weekOffset*7+i);return d.toISOString().slice(0,10)})}
function calendarView(){let days=getWeek();return heading('Make room for good conversations.','Discovery calls, check-ins, and next steps. All times Eastern.',`<button class="button primary" data-action="new-booking">＋ Book a meeting</button>`)+`<section class="panel calendar-panel"><div class="panel-head"><div class="week-control"><button class="icon-button" data-week="-1" aria-label="Previous week">‹</button><h2>${prettyDate(days[0])} – ${prettyDate(days[4])}, ${days[0].slice(0,4)}</h2><button class="icon-button" data-week="1" aria-label="Next week">›</button></div><button class="button small" data-action="this-week">This week</button></div><div class="week-grid">${days.map(d=>`<section class="day-column ${d==='2026-09-24'?'is-today':''}"><div class="day-heading"><span>${new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</span><strong>${Number(d.slice(-2))}</strong></div><div class="day-events">${events.filter(e=>e.date===d).sort((a,b)=>a.time.localeCompare(b.time)).map(e=>`<button class="calendar-event ${find(e.client).color}" data-event="${e.id}"><span>${timeLabel(e.time)} · ${e.duration} min</span><strong>${esc(e.title)}</strong><small>${esc(find(e.client).company)}</small><span class="event-video">▣ Video call</span></button>`).join('')||'<p class="free-day">No meetings</p>'}</div></section>`).join('')}</div></section><div class="calendar-footer"><span class="pill green">${events.filter(e=>days.includes(e.date)).length} meetings this week</span><span>Demo calendar · No external calendar connected</span></div>`}
function followupsView(){let list=clients.filter(c=>c.kind==='followup'&&c.need&&!['Won','Lost'].includes(c.stage)).sort((a,b)=>a.due.localeCompare(b.due));return heading('A thoughtful nudge goes a long way.','Keep proposals moving without keeping it all in your head.')+`<div class="followup-intro"><span class="spark">✧</span><div><strong>You set the pace. Relay prepares the words.</strong><p>Every follow-up stays in your review queue until you approve it.</p></div></div><section class="panel"><div class="panel-head"><h2>Upcoming follow-ups</h2><span class="pill">${list.length} waiting</span></div>${list.map(c=>`<div class="followup-row">${avatar(c)}<div class="followup-client"><h3>${esc(c.company)}</h3><p>${esc(c.name)} · ${money(c.value)} proposal</p></div><div class="followup-preview"><strong>${c.due<='2026-09-24'?'Due today':prettyDate(c.due)}</strong><p>${esc(c.draft)}</p></div><div class="row-actions"><button class="button small" data-snooze="${c.id}">Snooze</button><button class="button primary small" data-review="${c.id}">Review draft ↗</button></div></div>`).join('')||'<div class="empty">All follow-ups are up to date.<p>Your next conversations are waiting in the inbox.</p></div>'}</section>`}
function settingsView(){return heading('Your business. Your way.','Give your coordinator the context to sound like part of your team.')+`<form id="settings-form" class="settings-layout"><section class="panel settings-panel"><div class="panel-head"><h2>Business profile</h2><span class="pill">Demo workspace</span></div><div class="form-body"><div class="form-grid"><label>Business name<input name="name" required maxlength="80" value="${esc(settings.name)}"></label><label>Your name<input name="owner" required maxlength="80" value="${esc(settings.owner)}"></label></div><label>Services you offer<textarea name="services" required rows="3" maxlength="500">${esc(settings.services)}</textarea></label><div class="form-grid"><label>Starting project budget ($)<input name="minimum" type="number" min="0" max="1000000" required value="${settings.minimum}"></label><label>Reply tone<select name="tone">${['Warm and professional','Concise and direct','Friendly and conversational'].map(t=>`<option ${settings.tone===t?'selected':''}>${t}</option>`).join('')}</select></label></div><label>Questions for new clients<textarea name="questions" required maxlength="600" rows="3">${esc(settings.questions)}</textarea></label><div class="form-bottom"><span>Applies to new inquiry suggestions.</span><button class="button primary" type="submit">Save preferences</button></div></div></section><aside><section class="panel"><div class="panel-head"><h2>You stay in control</h2></div><div class="guardrail"><span>✓</span><div><strong>Review before sending</strong><p>Every message waits for your approval.</p></div></div><div class="guardrail"><span>✓</span><div><strong>Confirm before booking</strong><p>Choose the client, date, and available time.</p></div></div><div class="guardrail"><span>✓</span><div><strong>Clear boundaries</strong><p>Project scope and pricing remain yours to agree.</p></div></div></section><section class="panel connection-panel"><div class="panel-head"><h2>Connections</h2></div><div class="connection"><span>Email</span><span class="pill gray">Simulated</span></div><div class="connection"><span>Calendar</span><span class="pill gray">Simulated</span></div><p>Connect live accounts in a future version.</p></section></aside></form>`}
function showModal(title,body){$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div>${body}`;$('#modal').showModal()}
function clientModal(id){let c=find(id);if(!c)return;showModal(esc(c.company),`<div class="modal-body"><div class="client-summary">${avatar(c)}<div><strong>${esc(c.name)}</strong><p>${esc(c.email)}</p></div><strong>${money(c.value)}</strong></div><p class="muted">${esc(c.note)}</p><form id="stage-form" data-id="${c.id}"><label>Client stage<select name="stage">${stages.map(s=>`<option ${s===c.stage?'selected':''}>${s}</option>`).join('')}</select></label><div class="modal-actions"><button type="button" class="button" data-review="${c.id}">Open conversation</button><button class="button primary" type="submit">Update stage</button></div><p class="text-small muted">Changing a stage does not cancel an existing meeting.</p></form></div>`)}
function bookingModal(id,eventId){let existing=events.find(e=>e.id===Number(eventId))||events.find(e=>e.client===Number(id));let c=find(id)||find(existing?.client)||clients[0];showModal(existing?'Manage meeting':'Book a discovery call',`<form id="booking-form" data-event="${existing?.id||''}" class="modal-body"><p class="modal-subtitle">Reserve 30 minutes, Monday through Friday, 9 AM–5 PM Eastern.</p><label>Client<select name="client" ${existing?'disabled':''}>${clients.filter(x=>existing?x.id===existing.client:!['Won','Lost'].includes(x.stage)).map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.name)} · ${esc(x.company)}</option>`).join('')}</select></label><label>Meeting title<input name="title" required maxlength="80" value="${esc(existing?.title||'Discovery call')}"></label><div class="form-grid"><label>Date<input name="date" type="date" required min="2026-09-24" max="2027-12-31" value="${existing?.date||'2026-09-25'}"></label><label>Time (Eastern)<select name="time" required></select></label></div><div class="booking-note">▣ Video call · 30 minutes<br><small>This creates a demo booking. No invitation will be sent.</small></div><div id="booking-error" role="alert" class="error"></div><div class="modal-actions">${existing?`<button type="button" class="button danger" data-cancel-event="${existing.id}">Cancel meeting</button>`:'<button type="button" class="button" data-action="close-modal">Never mind</button>'}<button class="button primary" type="submit">${existing?'Save changes':'Confirm booking'}</button></div></form>`);updateSlots(existing?.time)}
function updateSlots(preferred){const form=$('#booking-form');if(!form)return;let date=form.elements.date.value,eventId=Number(form.dataset.event),select=form.elements.time;let slots=[];for(let h=9;h<17;h++)for(let m of ['00','30'])slots.push(`${String(h).padStart(2,'0')}:${m}`);let weekday=new Date(date+'T12:00:00').getDay();if(weekday===0||weekday===6){select.innerHTML='<option value="">Choose a weekday</option>';return}let available=slots.filter(t=>!events.some(e=>e.id!==eventId&&e.date===date&&e.time===t));select.innerHTML=available.map(t=>`<option value="${t}" ${t===preferred?'selected':''}>${timeLabel(t)}</option>`).join('');if(!available.length)select.innerHTML='<option value="">No times available</option>'}
function inquiryModal(){showModal('Try a new client inquiry',`<form id="inquiry-form" class="modal-body"><p class="modal-subtitle">Add a sample prospect and see how Relay prepares a reply using your business preferences.</p><div class="form-grid"><label>Client name<input name="name" required maxlength="70" placeholder="Jordan Lee"></label><label>Company<input name="company" required maxlength="80" placeholder="Brightside"></label></div><label>Project budget ($)<input name="value" required type="number" min="0" max="1000000" value="7500"></label><label>Their message<textarea name="message" rows="4" required maxlength="2000" placeholder="We’re looking for help with…"></textarea></label><div class="booking-note">Suggestions in this prototype use sample templates, not a live AI model.</div><div class="modal-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Create inquiry & draft ↗</button></div></form>`)}
function log(text){activity.unshift({text,time:'Just now'})}
function approveReply(id,text){let c=find(id);if(!c||!text?.trim())throw Error('Write a reply before sending.');c.sent.push({text:text.trim()});c.need=false;c.draft='';c.time='Just now';log(`Reply approved for ${c.company}`);render();return {clientId:c.id,status:'sent_in_demo',externalMessageSent:false}}
function book(data){let c=find(data.client),existing=events.find(e=>e.id===Number(data.event));if(!c)throw Error('Choose a client.');if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||data.date<'2026-09-24'||data.date>'2027-12-31')throw Error('Choose a date between Sep 24, 2026 and Dec 31, 2027.');if([0,6].includes(new Date(data.date+'T12:00:00').getDay()))throw Error('Meetings are available Monday through Friday.');if(!/^(09|1[0-6]):(00|30)$/.test(data.time))throw Error('Choose an available time.');if(events.some(e=>e.id!==existing?.id&&e.date===data.date&&e.time===data.time))throw Error('That time has been booked. Choose another.');if(!data.title.trim())throw Error('Enter a meeting title.');if(!existing&&events.some(e=>e.client===c.id))throw Error('This client already has a meeting. Open their existing meeting to reschedule.');let event={id:existing?.id||nextEvent++,client:c.id,date:data.date,time:data.time,title:data.title.trim(),duration:30};if(existing)Object.assign(existing,event);else{events.push(event);if(['New inquiry','Qualified'].includes(c.stage))c.stage='Meeting booked'}log(`${existing?'Meeting rescheduled':'Meeting booked'} with ${c.company}`);return event}
document.addEventListener('click',e=>{let b=e.target.closest('button,[data-view]');if(!b)return;if(b.dataset.view){navTo(b.dataset.view);return}if(b.dataset.review){$('#modal').close();selected=Number(b.dataset.review);inboxFilter='all';inboxQuery='';navTo('inbox');return}if(b.dataset.thread){selected=Number(b.dataset.thread);render();return}if(b.dataset.filter){inboxFilter=b.dataset.filter;render();return}if(b.dataset.send){try{approveReply(b.dataset.send,$('#reply-text').value);toast('Reply sent in the demo. No real email was sent.')}catch(err){toast(err.message)}return}if(b.dataset.client){clientModal(b.dataset.client);return}if(b.dataset.book){bookingModal(b.dataset.book);return}if(b.dataset.event){bookingModal(null,b.dataset.event);return}if(b.dataset.week){weekOffset+=Number(b.dataset.week);render();return}if(b.dataset.snooze){let c=find(b.dataset.snooze);let date=new Date(c.due+'T12:00:00');date.setDate(date.getDate()+2);c.due=date.toISOString().slice(0,10);log(`Follow-up with ${c.company} moved to ${prettyDate(c.due)}`);render();toast(`Follow-up moved to ${prettyDate(c.due)}.`);return}if(b.dataset.cancelEvent){let event=events.find(x=>x.id===Number(b.dataset.cancelEvent));let c=find(event.client);events=events.filter(x=>x.id!==event.id);if(c.stage==='Meeting booked')c.stage='Qualified';log(`Meeting canceled with ${c.company}`);$('#modal').close();render();toast('Demo meeting canceled.');return}if(b.id==='reset'){showModal('Reset this demo?',`<div class="modal-body"><p>This will restore the sample clients, meetings, and preferences. Your demo changes will be cleared.</p><div class="modal-actions"><button class="button" data-action="close-modal">Keep exploring</button><button class="button primary" data-action="confirm-reset">Reset demo</button></div></div>`);return}switch(b.dataset.action){case'close-modal':$('#modal').close();break;case'new-inquiry':inquiryModal();break;case'new-booking':bookingModal();break;case'this-week':weekOffset=0;render();break;case'confirm-reset':location.hash='today';location.reload();break}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;inboxQuery=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.id==='reply-text'){find(selected).draft=e.target.value}});
document.addEventListener('change',e=>{if(e.target.closest('#booking-form')&&e.target.name==='date')updateSlots()});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(f.id==='settings-form'){settings={...settings,...d,minimum:Number(d.minimum)};log('Business preferences updated');render();toast('Preferences saved for this demo session.')}if(f.id==='stage-form'){let c=find(f.dataset.id);c.stage=d.stage;log(`${c.company} moved to ${d.stage}`);$('#modal').close();render();toast('Client stage updated.')}if(f.id==='inquiry-form'){let c={id:nextClient++,name:d.name.trim(),company:d.company.trim(),initials:d.name.trim().split(/\s+/).map(n=>n[0]).slice(0,2).join('').toUpperCase(),color:'purple',email:'new-client@example.com',subject:'New project inquiry',message:d.message.trim(),stage:'New inquiry',value:Number(d.value),source:'Demo inquiry',time:'Just now',kind:'reply',due:'2026-09-24',need:true,sent:[],note:'New inquiry · Needs qualification'};c.draft=draftFor(c);clients.unshift(c);log(`New inquiry from ${c.company}`);selected=c.id;inboxFilter='all';inboxQuery='';$('#modal').close();navTo('inbox');toast('Inquiry added. Your suggested reply is ready.')}if(f.id==='booking-form'){try{let existing=events.find(x=>x.id===Number(f.dataset.event));let ev=book({...d,client:existing?.client||Number(d.client),event:f.dataset.event});$('#modal').close();let date=new Date(ev.date+'T12:00:00');weekOffset=Math.floor((date-new Date('2026-09-21T12:00:00'))/604800000);navTo('calendar');toast(`Meeting ${existing?'updated':'booked'} for ${prettyDate(ev.date)} at ${timeLabel(ev.time)}.`)}catch(err){$('#booking-error').textContent=err.message}}});
window.addEventListener('hashchange',()=>{let next=location.hash.slice(1);if(navs.some(n=>n[0]===next)){view=next;render()}});
if(navs.some(n=>n[0]===location.hash.slice(1)))view=location.hash.slice(1);render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'relay_read_demo_workspace',description:'Read sample clients and bookings in the current Relay prototype. No real accounts are connected.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object.');return {clients:clients.map(({id,name,company,stage,value})=>({id,name,company,stage,value})),events}}},{name:'relay_open_client_conversation',description:'Navigate to a sample client conversation. Does not send or approve a reply.',inputSchema:{type:'object',properties:{clientId:{type:'integer'}},required:['clientId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!Number.isInteger(input?.clientId)||!find(input.clientId)||Object.keys(input).some(k=>k!=='clientId'))throw Error('A valid clientId is required.');selected=input.clientId;inboxFilter='all';inboxQuery='';navTo('inbox');return {view,clientId:selected}}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
